#include <algorithm>
#include <cstdint>
#include <format>
#include <iostream>
#include <vector>

// What gz-sensors does with an update rate, from Sensor.cc: the period between updates is
// 1 / rate seconds cast to whole milliseconds, which truncates, and a sensor fires on the first
// simulation step at or after that period, then catches up without queueing what it missed.
struct Delivery {
  std::int64_t period_ms;    // the whole milliseconds the cast leaves
  std::int64_t gaps;         // how many gaps between firings the window held
  std::int64_t spanned_ms;   // from the first firing to the last
  std::int64_t shortest_ms;  // the shortest gap between two firings
  std::int64_t longest_ms;   // the longest
};

[[nodiscard]] Delivery deliver(double requested_hz, std::int64_t step_ms, std::int64_t window_ms) {
  const std::int64_t period_ms = static_cast<std::int64_t>(1000.0 / requested_hz);  // the truncating cast
  Delivery result{
      .period_ms = period_ms, .gaps = 0, .spanned_ms = 0, .shortest_ms = window_ms, .longest_ms = 0};
  std::int64_t next_ms = 0;
  std::int64_t first_fire_ms = -1;
  std::int64_t last_fire_ms = -1;
  for (std::int64_t now_ms = 0; now_ms < window_ms; now_ms += step_ms) {
    if (now_ms < next_ms) continue;
    if (last_fire_ms >= 0) {
      const std::int64_t gap = now_ms - last_fire_ms;
      result.shortest_ms = std::min(result.shortest_ms, gap);
      result.longest_ms = std::max(result.longest_ms, gap);
      ++result.gaps;
    } else {
      first_fire_ms = now_ms;
    }
    last_fire_ms = now_ms;
    next_ms += period_ms;
    while (next_ms <= now_ms) next_ms += period_ms;  // catch up, as Sensor.cc does
  }
  result.spanned_ms = last_fire_ms - first_fire_ms;
  return result;
}

int main() {
  constexpr std::int64_t window_ms = 10'000;  // ten seconds of simulated time
  std::cout << std::format("{:>9} {:>4} {:>8} {:>10} {:>8} {:>8} {:>8}\n", "asked Hz", "step", "period",
                           "delivered", "error", "shortest", "longest");
  for (const std::int64_t step_ms : std::vector<std::int64_t>{1, 4}) {
    for (const double asked_hz : {5.0, 10.0, 15.0, 30.0, 50.0, 60.0, 300.0}) {
      const Delivery got = deliver(asked_hz, step_ms, window_ms);
      const double mean_gap_ms = static_cast<double>(got.spanned_ms) / static_cast<double>(got.gaps);
      const double delivered_hz = 1000.0 / mean_gap_ms;
      const double error = 100.0 * (delivered_hz - asked_hz) / asked_hz;
      std::cout << std::format("{:>9.0f} {:>3}ms {:>6}ms {:>8.2f}Hz {:>+7.1f}% {:>6}ms {:>6}ms\n", asked_hz,
                               step_ms, got.period_ms, delivered_hz, error, got.shortest_ms, got.longest_ms);
    }
  }
}
